function j(string $f):array{$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];} function sj(string $f,array $x):bool{$l=fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$q=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);if($q===false||file_put_contents($t,$q,LOCK_EX)===false)return false;@chmod($t,0640);return rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function e(string $x):string{return htmlspecialchars($x,ENT_QUOTES,'UTF-8');} function now():string{return date('Y-m-d H:i:s');} function td():string{return date('Y-m-d');} function go(string $u):never{header('Location: '.$u);exit;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];} function cf():string{return '<input type="hidden" name="csrf" value="'.e(csrf()).'">';} function okc():bool{return isset($_POST['csrf'],$_SESSION['csrf'])&&hash_equals((string)$_SESSION['csrf'],(string)$_POST['csrf']);}
function fl(string $m,string $t='ok'):void{$_SESSION['fl']=[$m,$t];} function popfl():?array{$x=$_SESSION['fl']??null;unset($_SESSION['fl']);return is_array($x)?$x:null;} function cfg():array{return array_merge(['daily_quota'=>20,'commission_percent'=>30,'company_name'=>'وب ساز','support_phone'=>'','welcome_text'=>''],j(S));}
function br():?array{$id=(string)($_SESSION['bid']??'');foreach(j(B) as $b)if(($b['id']??'')===$id)return $b;return null;} function admin():bool{return !empty($_SESSION['adm']);} function lb(string $s):string{return ['new'=>'جدید','won'=>'سفارش قطعی','interested'=>'مشتری راغب','followup'=>'نیاز به پیگیری','no_answer'=>'جواب نداد','cancelled'=>'کنسل','bad_info'=>'اطلاعات اشتباه'][$s]??$s;} function tone(string $s):string{return match($s){'won'=>'good','interested'=>'cyan','followup'=>'warn','cancelled','bad_info'=>'bad','no_answer'=>'gray',default=>'blue'};}
function code():string{do{$c=(string)random_int(1000,9999);$u=false;foreach(j(B) as $b)if(($b['code']??'')===$c)$u=true;}while($u);return $c;} function lead(string $id):?array{foreach(j(L) as $x)if(($x['id']??'')===$id)return $x;return null;} function branchBy(string $id):?array{foreach(j(B) as $x)if(($x['id']??'')===$id)return $x;return null;}
function event(string $bid,string $aid,string $lid,string $st,string $n=''):void{$x=j(EV);$x[]=['id'=>'E'.bin2hex(random_bytes(5)),'branch_id'=>$bid,'assignment_id'=>$aid,'lead_id'=>$lid,'status'=>$st,'note'=>$n,'created_at'=>now()];if(count($x)>20000)$x=array_slice($x,-20000);sj(EV,$x);} 
function daily(string $bid):void{$q=max(1,min(100,(int)(cfg()['daily_quota']??20)));$as=j(A);$ls=j(L);$day=td();$n=0;foreach($as as $a)if(($a['branch_id']??'')===$bid&&($a['date']??'')===$day)$n++;$need=$q-$n;if($need<=0)return;$ever=[];$today=[];foreach($as as $a){if(($a['branch_id']??'')===$bid)$ever[$a['lead_id']??'']=1;if(($a['date']??'')===$day)$today[$a['lead_id']??'']=1;}foreach($ls as $x){if($need<=0)break;$id=(string)($x['id']??'');if(!$id||(isset($x['active'])&&!$x['active'])||isset($ever[$id])||isset($today[$id]))continue;$as[]=['id'=>'A'.bin2hex(random_bytes(5)),'branch_id'=>$bid,'lead_id'=>$id,'date'=>$day,'status'=>'new','note'=>'','followup_at'=>'','project_type'=>'','deal_value'=>'','created_at'=>now(),'updated_at'=>''];$ever[$id]=1;$today[$id]=1;$need--;}sj(A,$as);} 
function bas(string $bid):array{$x=array_values(array_filter(j(A),fn($a)=>($a['branch_id']??'')===$bid));usort($x,fn($a,$b)=>strcmp((string)($b['created_at']??''),(string)($a['created_at']??'')));return $x;} function counts(array $x):array{$o=['all'=>count($x),'new'=>0,'won'=>0,'interested'=>0,'followup'=>0,'no_answer'=>0,'cancelled'=>0,'bad_info'=>0];foreach($x as $a){$s=$a['status']??'new';if(isset($o[$s]))$o[$s]++;}return $o;}
function post(string $a):bool{return $_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')===$a;} function money(string $x):string{return preg_replace('/\D/','',$x)??'';}

$action=(string)($_POST['action']??$_GET['action']??'');
if(post('register')){if(!okc())exit('درخواست نامعتبر');$name=trim((string)($_POST['name']??''));$mobile=preg_replace('/\D/','',(string)($_POST['mobile']??''))??'';$city=trim((string)($_POST['city']??''));$p=(string)($_POST['password']??'');$ref=trim((string)($_POST['ref']??''));if(mb_strlen($name)<3||!preg_match('/^09\d{9}$/',$mobile)||strlen($p)<8){fl('اطلاعات ثبت‌نام معتبر نیست. رمز حداقل ۸ کاراکتر باشد.','err');go('./?mode=register');}$rows=j(B);foreach($rows as $r)if(($r['mobile']??'')===$mobile){fl('این شماره قبلاً ثبت شده است.','err');go('./?mode=login');}$id='B'.bin2hex(random_bytes(6));$rows[]=['id'=>$id,'code'=>code(),'name'=>$name,'mobile'=>$mobile,'city'=>$city,'password_hash'=>password_hash($p,PASSWORD_DEFAULT),'active'=>true,'referrer_code'=>$ref,'created_at'=>now(),'last_login_at'=>now()];sj(B,$rows);session_regenerate_id(true);$_SESSION['bid']=$id;daily($id);fl('ثبت‌نام انجام شد و پنل شما آماده است.');go('./');}
if(post('login')){if(!okc())exit('درخواست نامعتبر');$u=trim((string)($_POST['username']??''));$p=(string)($_POST['password']??'');$rows=j(B);foreach($rows as &$r)if((($r['mobile']??'')===$u||($r['code']??'')===$u)&&!empty($r['active'])&&password_verify($p,(string)($r['password_hash']??''))){$r['last_login_at']=now();sj(B,$rows);session_regenerate_id(true);$_SESSION['bid']=$r['id'];daily((string)$r['id']);go('./');}unset($r);fl('شماره/کد یا رمز عبور صحیح نیست.','err');go('./?mode=login');}
if($action==='logout'){unset($_SESSION['bid']);session_regenerate_id(true);go('./');}
if(post('update_assignment')&&($b=br())){if(!okc())exit('درخواست نامعتبر');$aid=(string)($_POST['assignment_id']??'');$st=(string)($_POST['status']??'new');if(!in_array($st,['new','won','interested','followup','no_answer','cancelled','bad_info'],true))$st='new';$note=trim((string)($_POST['note']??''));$fu=trim((string)($_POST['followup_at']??''));$pt=trim((string)($_POST['project_type']??''));$dv=money((string)($_POST['deal_value']??''));$rows=j(A);$lid='';foreach($rows as &$r)if(($r['id']??'')===$aid&&($r['branch_id']??'')===$b['id']){$lid=(string)$r['lead_id'];$r['status']=$st;$r['note']=$note;$r['followup_at']=$fu;$r['project_type']=$pt;$r['deal_value']=$dv;$r['updated_at']=now();break;}unset($r);sj(A,$rows);event((string)$b['id'],$aid,$lid,$st,$note);fl('نتیجه تماس ذخیره شد.');go('./?view=leads#lead-'.$aid);}
if(post('update_profile')&&($b=br())){if(!okc())exit('درخواست نامعتبر');$n=trim((string)($_POST['name']??''));$c=trim((string)($_POST['city']??''));$rows=j(B);foreach($rows as &$r)if(($r['id']??'')===$b['id']){$r['name']=$n;$r['city']=$c;break;}unset($r);sj(B,$rows);fl('اطلاعات حساب ذخیره شد.');go('./?view=profile');}
if(post('branch_password')&&($b=br())){if(!okc())exit('درخواست نامعتبر');$old=(string)($_POST['old']??'');$new=(string)($_POST['new']??'');if(!password_verify($old,(string)$b['password_hash'])||strlen($new)<8){fl('رمز فعلی اشتباه است یا رمز جدید کوتاه است.','err');go('./?view=profile');}$rows=j(B);foreach($rows as &$r)if(($r['id']??'')===$b['id']){$r['password_hash']=password_hash($new,PASSWORD_DEFAULT);break;}unset($r);sj(B,$rows);fl('رمز عبور تغییر کرد.');go('./?view=profile');}
if(post('admin_login')){if(!okc())exit('درخواست نامعتبر');$a=j(AD);if(hash_equals((string)($a['username']??''),trim((string)($_POST['username']??'')))&&password_verify((string)($_POST['password']??''),(string)($a['password_hash']??''))){session_regenerate_id(true);$_SESSION['adm']=1;go('./?admin=1');}fl('ورود مدیر ناموفق بود.','err');go('./?admin=1');}
