if(post('add_leads')&&admin()){if(!okc())exit('درخواست نامعتبر');$raw=trim((string)($_POST['bulk']??''));$rows=j(L);$known=[];foreach($rows as $r)$known[$r['phone']??'']=1;$n=0;$skip=0;foreach(preg_split('/\R/u',$raw) as $line){$line=trim($line);if(!$line)continue;$p=array_map('trim',explode('|',$line));$ph=preg_replace('/[^0-9+]/','',$p[1]??'')??'';if(!$ph||isset($known[$ph])){$skip++;continue;}$rows[]=['id'=>'L'.bin2hex(random_bytes(6)),'name'=>$p[0]??'مشتری','phone'=>$ph,'business'=>$p[2]??'','city'=>$p[3]??'','category'=>$p[4]??'','proposal'=>$p[5]??'طراحی سایت حرفه‌ای و مسیر جذب مشتری','script'=>$p[6]??'سلام وقت بخیر، از مجموعه وب ساز تماس می‌گیرم. کسب‌وکار شما را بررسی کردیم و یک پیشنهاد مشخص برای بهتر شدن جذب مشتری داریم. اگر دو دقیقه فرصت دارید خیلی کوتاه توضیح می‌دهم.','source'=>$p[7]??'ورودی مدیر','active'=>true,'created_at'=>now()];$known[$ph]=1;$n++;}sj(L,$rows);fl("$n فرصت اضافه شد".($skip?"؛ $skip مورد تکراری/نامعتبر رد شد.":'.'));go('./?admin=1&view=leads');}
if(post('toggle_branch')&&admin()){if(!okc())exit('درخواست نامعتبر');$id=(string)($_POST['id']??'');$rows=j(B);foreach($rows as &$r)if(($r['id']??'')===$id){$r['active']=empty($r['active']);break;}unset($r);sj(B,$rows);fl('وضعیت نمایندگی تغییر کرد.');go('./?admin=1&view=branches');}
if(post('assign_now')&&admin()){if(!okc())exit('درخواست نامعتبر');$n=0;foreach(j(B) as $r)if(!empty($r['active'])){daily((string)$r['id']);$n++;}fl("سهمیه امروز برای $n نمایندگی بررسی شد.");go('./?admin=1');}
if(post('save_settings')&&admin()){if(!okc())exit('درخواست نامعتبر');$c=cfg();$c['daily_quota']=max(1,min(100,(int)($_POST['daily_quota']??20)));$c['commission_percent']=max(0,min(100,(int)($_POST['commission_percent']??30)));$c['company_name']=trim((string)($_POST['company_name']??'وب ساز'));$c['support_phone']=trim((string)($_POST['support_phone']??''));$c['welcome_text']=trim((string)($_POST['welcome_text']??''));sj(S,$c);fl('تنظیمات ذخیره شد.');go('./?admin=1&view=settings');}

$isAdmin=isset($_GET['admin']);$b=br();if($b)daily((string)$b['id']);$view=preg_replace('/[^a-z_]/','',(string)($_GET['view']??'dashboard'))?:'dashboard';$mode=(string)($_GET['mode']??'login');$c=cfg();$flash=popfl();
function headx(string $t):void{echo '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#11151c"><title>'.e($t).' | وب ساز</title><link rel="stylesheet" href="./style.css?v=2"></head><body>';}
function flash(?array $f):void{if($f)echo '<div class="alert '.(($f[1]??'ok')==='err'?'err':'ok').'">'.e((string)$f[0]).'</div>';}
function top(array $b=null,bool $adm=false):void{echo '<header class="top"><div class="wrap topin"><a class="brand" href="./"><i>W</i><span>وب ساز<small>سامانه فعالیت نمایندگی</small></span></a><div class="user">'.e($adm?'مدیریت مرکزی':(string)($b['name']??'نمایندگی')).' <a class="btn light sm" href="?action='.($adm?'admin_logout':'logout').'">خروج</a></div></div></header>';}
function nav(string $v,array $b=null,bool $adm=false):void{$it=$adm?['dashboard'=>'نمای کلی','branches'=>'نمایندگی‌ها','leads'=>'بانک فرصت‌ها','activity'=>'فعالیت و نتایج','settings'=>'تنظیمات']:['dashboard'=>'داشبورد','leads'=>'فرصت‌های امروز','followups'=>'پیگیری‌ها','history'=>'سوابق','profile'=>'حساب من','help'=>'راهنمای فروش'];echo '<aside class="side"><div class="sidehead"><b>'.e($adm?'مدیریت وب ساز':(string)$b['name']).'</b><small>'.($adm?'کنترل کل سیستم':'کد نمایندگی: '.e((string)$b['code'])).'</small></div>';foreach($it as $k=>$x)echo '<a class="'.($v===$k?'on':'').'" href="?'.($adm?'admin=1&':'').'view='.$k.'">'.$x.'</a>';echo '</aside><nav class="mobile">';foreach($it as $k=>$x)echo '<a class="'.($v===$k?'on':'').'" href="?'.($adm?'admin=1&':'').'view='.$k.'">'.$x.'</a>';echo '</nav>';}
function guide(array $l):string{$biz=e((string)($l['business']?:$l['name']??'کسب‌وکار'));$pr=e((string)($l['proposal']??'طراحی سایت و جذب مشتری'));return '<div class="guide"><div><b>۱. شروع تماس</b><p>'.e((string)($l['script']??'سلام وقت بخیر، از وب ساز تماس می‌گیرم.')).'</p></div><div><b>۲. کشف نیاز</b><p>بپرس: «الان بیشتر مشتری‌ها از چه طریقی شما را پیدا می‌کنند؟» و «مهم‌ترین خدمت یا محصولی که می‌خواهید بیشتر بفروشید چیست؟»</p></div><div><b>۳. پیشنهاد متناسب</b><p>برای '.$biz.' روی '.$pr.' تمرکز کن و نتیجه را ساده توضیح بده.</p></div><div><b>۴. اگر تردید داشت</b><p>مخالفت نکن؛ پیشنهاد ارسال نمونه یا بررسی کوتاه رایگان را بده تا قدم بعدی کوچک باشد.</p></div><div><b>۵. پایان تماس</b><p>حتماً یک اقدام بعدی مشخص کن: ارسال نمونه، زمان پیگیری یا شروع بررسی پروژه.</p></div><div><b>نکته</b><p>قول قطعی رتبه گوگل یا درآمد نده؛ روی کیفیت، نمونه‌کار و مسیر همکاری تمرکز کن.</p></div></div>';}
function card(array $a,int $i):void{$l=lead((string)$a['lead_id']);if(!$l)return;$st=(string)($a['status']??'new');$id=e((string)$a['id']);$ph=e((string)($l['phone']??''));echo '<article class="lead" id="lead-'.$id.'"><div class="leadtop"><div class="leadname"><i>'.($i+1).'</i><div><h3>'.e((string)($l['business']?:$l['name']??'مشتری')).'</h3><span>'.e((string)($l['city']??'')).' '.e((string)($l['category']??'')).'</span></div></div><div><a class="phone" href="tel:'.$ph.'">'.$ph.'</a><span class="pill '.tone($st).'">'.e(lb($st)).'</span></div></div><div class="actions"><a class="btn dark sm" href="tel:'.$ph.'">تماس</a><button class="btn light sm copy" type="button" data-copy="'.$ph.'">کپی شماره</button></div><div class="proposal"><b>پیشنهاد مناسب:</b> '.e((string)($l['proposal']??'طراحی سایت حرفه‌ای و مسیر جذب مشتری')).'</div><details><summary>سناریوی کامل تماس و نحوه صحبت</summary>'.guide($l).'</details><form method="post" class="result">'.cf().'<input type="hidden" name="action" value="update_assignment"><input type="hidden" name="assignment_id" value="'.$id.'"><b>نتیجه تماس</b><div class="statuses">';foreach(['won','interested','followup','no_answer','cancelled','bad_info','new'] as $x)echo '<label><input type="radio" name="status" value="'.$x.'" '.($st===$x?'checked':'').'><span>'.e(lb($x)).'</span></label>';echo '</div><div class="cols"><label>زمان پیگیری<input type="datetime-local" name="followup_at" value="'.e(str_replace(' ','T',(string)($a['followup_at']??''))).'"></label><label>نوع پروژه<input name="project_type" value="'.e((string)($a['project_type']??'')).'" placeholder="مثلاً سایت فروشگاهی"></label><label>ارزش تقریبی قرارداد<input inputmode="numeric" name="deal_value" value="'.e((string)($a['deal_value']??'')).'" placeholder="تومان"></label><label>یادداشت تماس<input name="note" value="'.e((string)($a['note']??'')).'" placeholder="خلاصه گفتگو"></label></div><button class="btn lime" type="submit">ذخیره نتیجه تماس</button></form></article>';}

